(7595570, 1225590, 50695, '<td valign="top">there''s a certain resonance of real and symbol here, the walkers, the stroller, the picture of a walker, the arrow pointing in the wrong direction, the road going off in the wrong direction, as if time were a confusion of perspectives, as if time were relative.</td>', 'there''s a certain resonance of real and symbol here, the walkers, the stroller, the picture of a walker, the arrow pointing in the wrong direction, the road going off in the wrong direction, as if time were a confusion of perspectives, as if time were relative.', '2018-09-09 19:38:06.000000', NULL, 1),
(7595571, 1225577, 50695, '<td valign="top">which ones are lost? the ones flowing with time or the ones outside of it, observing?</td>', 'which ones are lost? the ones flowing with time or the ones outside of it, observing?', '2018-09-09 19:38:40.000000', NULL, 1),
(7595572, 1225622, 50695, '<td valign="top">a meditation on slowness. the notorious slowness of the turtle, the slow deliberation of the tide</td>', 'a meditation on slowness. the notorious slowness of the turtle, the slow deliberation of the tide', '2018-09-09 19:39:26.000000', NULL, 1),
